namespace CheckoutWizard;

public class ShippingInfo
{
    public string Name { get; set; } = "";
    public string Address { get; set; } = "";
    public string City { get; set; } = "";
    public string ZipCode { get; set; } = "";
}

public class PaymentInfo
{
    public string CardNumber { get; set; } = "";
    public string ExpiryDate { get; set; } = "";
}

public class Order
{
    public ShippingInfo Shipping { get; set; } = new();
    public PaymentInfo Payment { get; set; } = new();
}

public interface IAddressValidator
{
    Task<bool> ValidateAddressAsync(string address, string city, string zip, CancellationToken ct);
}

@namespace CheckoutWizard

<div class="checkout-wizard">
    @if (_step == Step.Shipping)
    {
        <ShippingStep Shipping="@_order.Shipping"
                      OnNext="@HandleShippingComplete" />
    }
    else
    {
        <PaymentStep Payment="@_order.Payment"
                     OnBack="@HandleBackToShipping"
                     OnPlaceOrder="@HandlePlaceOrder" />
    }
</div>

@code {
    /// <summary>Raised when the user clicks "Place Order" with a completed order.</summary>
    [Parameter]
    public EventCallback<Order> OnOrderPlaced { get; set; }

    private readonly Order _order = new();
    private Step _step = Step.Shipping;

    private enum Step { Shipping, Payment }

    private void HandleShippingComplete()
    {
        _step = Step.Payment;
    }

    private void HandleBackToShipping()
    {
        _step = Step.Shipping;
    }

    private async Task HandlePlaceOrder()
    {
        await OnOrderPlaced.InvokeAsync(_order);
    }
}

@namespace CheckoutWizard
@inject IAddressValidator AddressValidator
@implements IDisposable

<h3>Shipping Information</h3>

<div class="shipping-form">
    <label>
        Name
        <input @bind="Shipping.Name" @bind:event="oninput" disabled="@_isValidating" />
    </label>

    <label>
        Address
        <input @bind="Shipping.Address" @bind:event="oninput" disabled="@_isValidating" />
    </label>

    <label>
        City
        <input @bind="Shipping.City" @bind:event="oninput" disabled="@_isValidating" />
    </label>

    <label>
        Zip Code
        <input @bind="Shipping.ZipCode" @bind:event="oninput" disabled="@_isValidating" />
    </label>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="validation-error" role="alert">@_errorMessage</div>
    }

    <button @onclick="HandleNext" disabled="@_isValidating">
        @if (_isValidating)
        {
            <span class="spinner" aria-hidden="true"></span>
            <span>Validating…</span>
        }
        else
        {
            <span>Next</span>
        }
    </button>
</div>

@code {
    [Parameter, EditorRequired]
    public ShippingInfo Shipping { get; set; } = default!;

    [Parameter]
    public EventCallback OnNext { get; set; }

    private bool _isValidating;
    private string? _errorMessage;

    // Cancels in-flight validation when the user retries or the component is disposed.
    private CancellationTokenSource? _validationCts;

    private async Task HandleNext()
    {
        _errorMessage = null;

        // Cancel any previous in-flight validation.
        CancelPendingValidation();

        if (string.IsNullOrWhiteSpace(Shipping.Name) ||
            string.IsNullOrWhiteSpace(Shipping.Address) ||
            string.IsNullOrWhiteSpace(Shipping.City) ||
            string.IsNullOrWhiteSpace(Shipping.ZipCode))
        {
            _errorMessage = "All shipping fields are required.";
            return;
        }

        _validationCts = new CancellationTokenSource();
        var token = _validationCts.Token;
        _isValidating = true;

        try
        {
            var isValid = await AddressValidator.ValidateAddressAsync(
                Shipping.Address, Shipping.City, Shipping.ZipCode, token);

            token.ThrowIfCancellationRequested();

            if (isValid)
            {
                await OnNext.InvokeAsync();
            }
            else
            {
                _errorMessage = "The address could not be verified. Please check and try again.";
            }
        }
        catch (OperationCanceledException)
        {
            // Validation was intentionally cancelled — nothing to do.
        }
        finally
        {
            _isValidating = false;
        }
    }

    private void CancelPendingValidation()
    {
        _validationCts?.Cancel();
        _validationCts?.Dispose();
        _validationCts = null;
    }

    public void Dispose()
    {
        CancelPendingValidation();
    }
}

@namespace CheckoutWizard

<h3>Payment Information</h3>

<div class="payment-form">
    <label>
        Card Number
        <input @bind="Payment.CardNumber" @bind:event="oninput" />
    </label>

    <label>
        Expiry Date
        <input @bind="Payment.ExpiryDate" @bind:event="oninput"
               placeholder="MM/YY" />
    </label>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="validation-error" role="alert">@_errorMessage</div>
    }

    <div class="button-group">
        <button @onclick="HandleBack" type="button">Back</button>
        <button @onclick="HandlePlaceOrder" type="button">Place Order</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public PaymentInfo Payment { get; set; } = default!;

    [Parameter]
    public EventCallback OnBack { get; set; }

    [Parameter]
    public EventCallback OnPlaceOrder { get; set; }

    private string? _errorMessage;

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }

    private async Task HandlePlaceOrder()
    {
        _errorMessage = null;

        if (string.IsNullOrWhiteSpace(Payment.CardNumber) ||
            string.IsNullOrWhiteSpace(Payment.ExpiryDate))
        {
            _errorMessage = "Card number and expiry date are required.";
            return;
        }

        await OnPlaceOrder.InvokeAsync();
    }
}

